test("casts over an instance of Grouped", () => {
  const theGrouped =
    TestCommonJsonization.loadMinimalGrouped();

  expect(
    OurTypes.isSomething(theGrouped)
  ).toStrictEqual(false);
  expect(
    OurTypes.asSomething(theGrouped)
  ).toBeNull();

  expect(
    OurTypes.isGrouped(theGrouped)
  ).toStrictEqual(true);
  expect(
    OurTypes.asGrouped(theGrouped)
  ).toStrictEqual(theGrouped);
});

